/**
 * India, by state and union territory, as SVG path data.
 *
 * Dissolved from the district boundaries published by the Survey of India, in
 * the depiction the Government requires: all 36 states and union territories
 * as constituted after the 2019 reorganisation, with Jammu and Kashmir and
 * Ladakh — Aksai Chin and Gilgit-Baltistan included — shown as Indian
 * territory. Projected Mercator and simplified to about a kilometre, which is
 * finer than a 1000-unit-wide map can draw.
 *
 * Generated, not hand-written. Names match master.State once case and a
 * leading "The" are set aside, which is what the dashboard keys on.
 *
 * `small` marks the ones too small to see at this scale — Chandigarh,
 * Lakshadweep, Puducherry and the like. They are drawn a marker at (cx, cy)
 * as well as their outline, so they can still be pointed at and read.
 */
export interface IndiaState {
  readonly name: string;
  readonly cx: number;
  readonly cy: number;
  readonly small: boolean;
  readonly d: string;
}

export const INDIA_WIDTH = 1000;
export const INDIA_HEIGHT = 1133;
export const INDIA_VIEWBOX = '0 0 1000 1133';

